$ErrorActionPreference = 'Stop'
$c = $PSScriptRoot
$r = Join-Path (Split-Path $c -Parent) 'learning-japanese'
$a = Join-Path (Split-Path $c -Parent) 'kanji-cards-android'
$head = (git -C $r rev-parse HEAD).Trim()
if ((git -C $r rev-parse 'HEAD^').Trim() -ne 'a70c9deb565e696772342675c2a9c99b09967e8a') {
    throw 'Unexpected signed checkpoint parent.'
}
if ((git -C $r log -1 --format='%G?').Trim() -ne 'G' -or (git -C $r status --porcelain)) {
    throw 'Content worktree not normally signed and clean.'
}
if ((git -C $a rev-parse HEAD).Trim() -ne '1c1b7bf42cc91d820a93169f1088dc647ac51c0d' -or
    (git -C $a status --porcelain)) { throw 'Dedicated Android state changed.' }
$p = Get-Content "$c\progress.json" -Raw | ConvertFrom-Json
if ($p.checkpoint -ne 579 -or $p.batch -ne '083' -or
    $p.stage -ne 'batch-083-combined-main-acceptance-in-progress') { throw 'Checkpoint context changed.' }
$body = @"
Batch 083 checkpoint580: **latest-main combined-tree acceptance passed; publication remains next**. Fresh origin/main is 21a5cb1328aadd437139a6b850f07298a2e2985d; normal non-rewriting merge returned already up to date. No teaching or runtime bytes changed after accepted two-family source/choice/visual reviews. Normally signed LOCAL evidence checkpoint: $head.

Fresh combined checks: all372 Python tests passed, validator0errors, vocabulary consistency, regenerated byte-unchanged manifest/version6dfe6a1e287ce5df, every8376 runtime hash, exact frozen membership, original985kanji/4942words/985strokes with recorded narrow exceptions,17direct word guards, two reciprocal pairs/two curated readings and pinned ten-stroke conversion passed. Four complete frozen lexical packets and12 raw-character occurrences were mechanically re-extracted/compared; this is not a new linguistic review. Local budget:8398entries,44,180,553retained bytes,44,448,891inflated bytes,30,187,434compressed bytes; all original18,000/42MiB/80MiB/56MiB guards unchanged.

Fresh serial actual-sibling Android HOST: RealContentTest3 and RareHanTest1 executed with zero skips/failures/errors; BUILD SUCCESSFUL, all41tasks executed. Exact signed TESTONLYAndroid1c1b7bf4 atop unchanged productionf9, explicit JDK17/SDK, one worker and inherited host-only test init. No native/guest/app heap or archive guard increase. Parent19008 verified in ancestry; child never opens/reacquires/deletes/unlocks runner.lock.

Both original ClaudeOpus5.5/GPT6.1Sol initial, changed-choice and visual reports, actual models/session/exits/serial timings/source-and-returned-image hashes, corrected578 native terminal0 cases and all archived artifacts were reverified, not rerun. Exact accepted local native archive matches combined manifest/every runtime hash; it is **not public immutable-ZIP acceptance**. Original574 failure and all579 qualifications preserved, including resized viewport/uncaptured word-body headings, unverified final loading-tree timing/fallback-face identity, unavailable offline handwriting model, injected reference tracing/give-up not human recognition/MLKit/phone, and no AllUI/custom/random/padded/partial/larger/reverse-pool safety claim.

Evidence: docs/n1-sources/execution-580.json and docs/n1-reviews/batch-083-combined-acceptance-580, including lossless raw outputs, non-skipped XML and durable control recipes. **Next bounded execution: fresh-main recheck, normal signed owner fast-forward publication, exact remoteSHA/terminalgreenCI/EVERY immutable GitHub ZIP hash and budgets, durable publication/owner receipt before084.** No publication or084 here. Published remains109/1228,1119remaining; 凌 and its two necessary supporting words are accepted locally but batch083 is not delivered. Physical-phone/general-release/whole-set acceptance outstanding. No optional historical-session helpers or new permission denials.
"@
$bodyPath = "$c\batch-083-combined-580-issue.txt"
$payloadPath = "$c\batch-083-combined-580-issue-payload.json"
if (Test-Path $bodyPath) { throw 'Preserve existing issue attempt; do not repost blindly.' }
[IO.File]::WriteAllText($bodyPath, $body + "`n", [Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText($payloadPath, (@{body=$body} | ConvertTo-Json), [Text.UTF8Encoding]::new($false))
try {
    $env:GH_TOKEN = (gh auth token --user stop-cran).Trim()
    if ($LASTEXITCODE -ne 0 -or -not $env:GH_TOKEN) { throw 'Owner token unavailable.' }
    $login = (gh api user --jq .login).Trim()
    if ($LASTEXITCODE -ne 0 -or $login -ne 'stop-cran') { throw 'Owner identity mismatch.' }
    $posted = gh api repos/stop-cran/learning-japanese/issues/60/comments --method POST --input $payloadPath
    if ($LASTEXITCODE -ne 0) { throw 'Issue comment failed; preserve attempt and yield.' }
    [IO.File]::WriteAllText("$c\batch-083-combined-580-issue-posted.json", ($posted -join "`n"), [Text.UTF8Encoding]::new($false))
    $comment = ($posted -join "`n") | ConvertFrom-Json
    $verified = gh api "repos/stop-cran/learning-japanese/issues/comments/$($comment.id)"
    if ($LASTEXITCODE -ne 0) { throw 'Issue receipt retrieval failed.' }
    $receipt = ($verified -join "`n") | ConvertFrom-Json
    if ($receipt.user.login -ne 'stop-cran' -or
        $receipt.body.Replace("`r`n", "`n").TrimEnd() -ne $body.Replace("`r`n", "`n").TrimEnd()) {
        throw 'Issue author/body mismatch.'
    }
    [IO.File]::WriteAllText("$c\batch-083-combined-580-issue-verified.json", ($verified -join "`n"), [Text.UTF8Encoding]::new($false))
    Write-Output $receipt.html_url
} finally {
    Remove-Item Env:\GH_TOKEN -ErrorAction SilentlyContinue
}
